// A fictional, isolated network puzzle; it never accesses a real network.
export const NETWORK=[
 {id:0,x:10,y:50,name:'ТОЧКА ВХОДА',type:'entry',cost:0,risk:0},
 {id:1,x:29,y:24,name:'ШЛЮЗ A',type:'relay',cost:2,risk:14},
 {id:2,x:29,y:76,name:'ТИХИЙ КАНАЛ',type:'relay',cost:3,risk:6},
 {id:3,x:51,y:24,name:'АРХИВ',type:'cache',cost:2,risk:12},
 {id:4,x:51,y:76,name:'ЭКРАН',type:'shield',cost:2,risk:8},
 {id:5,x:72,y:50,name:'ЯДРО ДОСТУПА',type:'relay',cost:3,risk:18},
 {id:6,x:91,y:50,name:'ЦЕЛЕВОЙ УЗЕЛ',type:'goal',cost:3,risk:15}
];
export const LINKS=[[0,1],[0,2],[1,3],[2,4],[3,5],[4,5],[5,6]];
export function createNetwork(){return {owned:[0],trace:0,active:null,elapsed:0,started:false,won:false,lost:false,stealth:1,shield:false};}
export function canCapture(s,id){return !s.won&&!s.lost&&s.active===null&&!s.owned.includes(id)&&LINKS.some(([a,b])=>a===id&&s.owned.includes(b)||b===id&&s.owned.includes(a));}
export function beginCapture(s,id){if(!canCapture(s,id))return false;s.active=id;s.elapsed=0;s.started=true;return true;}
export function tickNetwork(s,dt){if(s.won||s.lost||!s.started)return;dt=Math.max(0,Math.min(dt,.25));s.trace+=dt*(s.shield?1.1:2);if(s.active!==null){const n=NETWORK[s.active];s.elapsed+=dt;if(s.elapsed>=n.cost){s.owned.push(n.id);s.trace+=n.risk;s.active=null;if(n.type==='shield'){s.shield=true;s.trace=Math.max(0,s.trace-18);}if(n.type==='cache')s.stealth++;if(n.type==='goal'&&s.trace<100)s.won=true;}}if(s.trace>=100){s.trace=100;s.lost=true;s.won=false;}}
export function cloak(s){if(!s.stealth||s.won||s.lost)return false;s.stealth--;s.trace=Math.max(0,s.trace-30);return true;}
export function mountNetwork(host,onComplete){
 let state=createNetwork(),selected=1,disposed=false,reported=false,last=performance.now(),raf;
 host.innerHTML=`<section class="net-game"><div class="net-mast"><div><small>ЦЕНТР ИНВЕСТ БАНК / АУДИТ ДОСТУПА</small><h2>Тихое проникновение<span> / 03</span></h2></div><span class="net-authorized">УЧЕБНЫЙ СТЕНД · ДОСТУП РАЗРЕШЁН</span></div><div class="net-status"><span>ОБНАРУЖЕНИЕ <b class="trace-number">0%</b></span><div class="trace-track"><i></i></div><span class="net-session">СЕССИЯ ГОТОВА</span></div><div class="net-layout"><div class="net-map"><svg viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true">${LINKS.map(([a,b])=>`<line data-link="${a}-${b}" x1="${NETWORK[a].x}" y1="${NETWORK[a].y}" x2="${NETWORK[b].x}" y2="${NETWORK[b].y}"/>`).join('')}</svg><div class="net-grid"></div>${NETWORK.map(n=>`<button class="net-node" data-node="${n.id}" style="left:${n.x}%;top:${n.y}%" aria-label="${n.name}"><span class="node-shape">${({entry:'◉',relay:'◇',cache:'▤',shield:'⬡',goal:'◎'})[n.type]}</span><small>${n.name}</small><em></em></button>`).join('')}<span class="map-coordinate">LOCAL SIMULATION / 127.0.0.1<br>TOPOLOGY — K-03</span></div><aside class="net-inspector"><small>ВЫБРАННЫЙ УЗЕЛ</small><h3 class="node-title"></h3><p class="node-info"></p><button class="net-capture">Захватить узел</button><button class="net-cloak">Скрыть след</button><div class="net-legend"><p><i></i> Ваши узлы</p><p><i></i> Доступен для захвата</p><p><i></i> Ещё нет соединения</p></div><p class="net-guide">Построй путь от входа к цели. Захватывай соседние узлы. «Экран» замедлит обнаружение, «Архив» даст дополнительное скрытие следа.</p></aside></div><div class="net-log" role="status">Выбери соседний узел и начни захват. До первого действия таймер не идёт.</div><button class="net-retry" hidden>Начать новую попытку</button><div class="lab-result" hidden></div></section>`;
 const q=s=>host.querySelector(s);const nodes=[...host.querySelectorAll('[data-node]')];
 function render(){const n=NETWORK[selected];q('.node-title').textContent=n.name;q('.node-info').textContent=state.owned.includes(selected)?'Узел под вашим контролем. Можно двигаться дальше.':`${n.cost} сек на захват · +${n.risk}% обнаружения. ${n.type==='shield'?'Снизит след на 18% и замедлит поиск.':n.type==='cache'?'Добавит заряд скрытия следа.':n.type==='goal'?'Завершит проверку безопасности.':'Открывает путь к соседним узлам.'}`;q('.net-capture').disabled=!canCapture(state,selected);q('.net-capture').textContent=state.active===selected?'Захват…':'Захватить узел';q('.net-cloak').textContent=`Скрыть след −30% / ${state.stealth}`;q('.net-cloak').disabled=!state.stealth||!state.started||state.won||state.lost;
 nodes.forEach((b,i)=>{b.classList.toggle('owned',state.owned.includes(i));b.classList.toggle('reachable',canCapture(state,i));b.classList.toggle('selected',selected===i);b.classList.toggle('capturing',state.active===i);b.querySelector('em').textContent=state.owned.includes(i)?'✓':state.active===i?Math.round(state.elapsed/NETWORK[i].cost*100)+'%':'';});host.querySelectorAll('[data-link]').forEach(l=>{const [a,b]=l.dataset.link.split('-').map(Number);l.classList.toggle('owned',state.owned.includes(a)&&state.owned.includes(b));});q('.trace-number').textContent=Math.floor(state.trace)+'%';q('.trace-track i').style.width=state.trace+'%';q('.net-session').textContent=state.won?'ДОСТУП ПОЛУЧЕН':state.lost?'СЕССИЯ ОБНАРУЖЕНА':state.active!==null?'ЗАХВАТ УЗЛА':state.started?'ИДЁТ ПОИСК':'СЕССИЯ ГОТОВА';q('.net-retry').hidden=!state.lost;
 }
 nodes.forEach((b,i)=>b.onclick=()=>{selected=i;render();});q('.net-capture').onclick=()=>{if(beginCapture(state,selected))q('.net-log').textContent='Захватываем '+NETWORK[selected].name+'. Система начала поиск.';render();};q('.net-cloak').onclick=()=>{if(cloak(state))q('.net-log').textContent='След уменьшен на 30%. Продолжай маршрут.';render();};q('.net-retry').onclick=()=>{state=createNetwork();selected=1;q('.net-log').textContent='Новая сессия. Попробуй путь через «Экран».';render();};
 function draw(now){if(disposed)return;raf=requestAnimationFrame(draw);const dt=(now-last)/1000;last=now;if(document.hidden)return;const old=state.active;tickNetwork(state,dt);if(old!==null&&state.active===null)q('.net-log').textContent=NETWORK[old].name+' под контролем. Выбери следующий узел.';if(state.lost)q('.net-log').textContent='Защитная система обнаружила сессию. Попробуй маршрут с меньшим риском или используй скрытие следа.';render();if(state.won&&!reported){reported=true;const r=q('.lab-result');r.hidden=false;r.innerHTML='<span>РАЗБОР РАБОТЫ</span><h3>Проверка завершена.</h3><p>Ты построил маршрут доступа через соседние узлы и контролировал обнаружение. Белый хакер работает с разрешения владельца, находит слабые места и передаёт отчёт для исправления. Эта игровая схема условна: она показывает связь доступа, маршрута и мониторинга, а не технику реального взлома.</p>';q('.net-log').textContent='Цель достигнута. Результат проверки передан владельцу.';onComplete();}}
 render();raf=requestAnimationFrame(draw);return()=>{disposed=true;cancelAnimationFrame(raf);};
}
